//! r-code-relay: the self-hosted relay binary (R16). Binds a plain WS
//! endpoint (deploy behind Caddy/nginx for TLS — relay-interface.md §4);
//! registration codes come from the environment (`R_CODE_RELAY_CODES`,
//! comma-separated one-time codes generated by the desktop console).

use r_code_relay::{serve, RelayState};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

#[tokio::main]
async fn main() {
    let bind = std::env::var("R_CODE_RELAY_BIND").unwrap_or_else(|_| "127.0.0.1:8787".into());
    let codes: HashMap<String, bool> = std::env::var("R_CODE_RELAY_CODES")
        .unwrap_or_default()
        .split(',')
        .filter(|code| !code.trim().is_empty())
        .map(|code| (code.trim().to_string(), true))
        .collect();
    if codes.is_empty() {
        eprintln!("r-code-relay: no registration codes configured (R_CODE_RELAY_CODES); refusing to serve");
        std::process::exit(2);
    }
    let listener = match tokio::net::TcpListener::bind(&bind).await {
        Ok(listener) => listener,
        Err(error) => {
            eprintln!("r-code-relay: bind {bind} failed: {error}");
            std::process::exit(1);
        }
    };
    eprintln!(
        "r-code-relay: serving on ws://{bind} with {} registration code(s)",
        codes.len()
    );
    serve(listener, RelayState::new(), Arc::new(Mutex::new(codes))).await;
}
